q = db.selectFrom('person').select((eb) => eb.fn.sum('age').over((ob) => ob.groups((fb) => fb.betweenFollowing(2).andUnboundedFollowing().excludeNoOthers())).as('s'))
check('between following and unbounded following exclude no others', q, {sql:'select sum("age") over(groups between $1 following and unbounded following exclude no others) as "s" from "person"', parameters:[2]})

// all and* variants
const variants = [
  ['andUnboundedPreceding', 'unbounded preceding', []],
  ['andPreceding', '$1 preceding', [1]],
  ['andCurrentRow', 'current row', []],
  ['andFollowing', '$1 following', [1]],
  ['andUnboundedFollowing', 'unbounded following', []],
]
for (const [m, sql, params] of variants) {
  q = db.selectFrom('person').select((eb) => eb.fn.sum('age').over((ob) => ob.range((fb) => fb.betweenUnboundedPreceding()[m](1))).as('s'))
