const noArg = ['andUnboundedPreceding','andCurrentRow','andUnboundedFollowing']
for (const m of noArg) {
  q = db.selectFrom('person').select((eb) => eb.fn.sum('age').over((ob) => ob.range((fb) => fb.betweenUnboundedPreceding()[m]())).as('s'))
  const end = m === 'andUnboundedPreceding' ? 'unbounded preceding' : m === 'andCurrentRow' ? 'current row' : 'unbounded following'
  check('and* '+m, q, {sql:`select sum("age") over(range between unbounded preceding and ${end}) as "s" from "person"`, parameters:[]})
}
const withArg = ['andPreceding','andFollowing']
for (const m of withArg) {
  q = db.selectFrom('person').select((eb) => eb.fn.sum('age').over((ob) => ob.range((fb) => fb.betweenUnboundedPreceding()[m](1))).as('s'))
  const end = m === 'andPreceding' ? '$1 preceding' : '$1 following'
  check('and* '+m, q, {sql:`select sum("age") over(range between unbounded preceding and ${end}) as "s" from "person"`, parameters:[1]})
}
// between* starters
const starters = [
  ['betweenUnboundedPreceding', 'unbounded preceding', null],
  ['betweenPreceding', '$1 preceding', [1]],
  ['betweenCurrentRow', 'current row', null],
  ['betweenFollowing', '$1 following', [1]],
]
for (const [m, start, arg] of starters) {
  q = db.selectFrom('person').select((eb) => eb.fn.sum('age').over((ob) => ob.rows((fb) => fb[m](... (arg || []))).as('s')))
}
// Actually call starters properly
for (const [m, start, arg] of starters) {
  q = db.selectFrom('person').select((eb) => eb.fn.sum('age').over((ob) => ob.rows((fb) => arg ? fb[m](1).andUnboundedFollowing() : fb[m]().andUnboundedFollowing())).as('s'))
  const params = arg ? [1] : []
  check('starter '+m, q, {sql:`select sum("age") over(rows between ${start} and unbounded following) as "s" from "person"`, parameters:params})
